let nextEnemyCombatOwnerGeneration = 1;

const STEER_RESPONSIVENESS = 8;
const SPAWN_LANE_JITTER_PX = CELL_SIZE * 0.3;
const NO_SEPARATION = { x: 0, y: 0 } as const;

function captureEnemyDeathVisual(enemy: EnemyEntity): Pick<
  EnemyDeathInfo,
  'textureKey' | 'frame' | 'displayWidth' | 'displayHeight' | 'rotation' | 'tint'
> {
  const sprite = enemy.sprite;
  return {
    textureKey: sprite.texture?.key ?? '',
    frame: sprite.frame?.name ?? '__BASE',
    displayWidth: Number.isFinite(sprite.displayWidth) ? sprite.displayWidth : Math.max(1, enemy.getSize()),
    displayHeight: Number.isFinite(sprite.displayHeight) ? sprite.displayHeight : Math.max(1, enemy.getSize()),
    rotation: Number.isFinite(sprite.rotation) ? sprite.rotation : 0,
    tint: sprite.tint ?? 0xffffff,
  };
}

export interface EnemyDeathInfo {
  readonly id: string;
  readonly kind: CoopDefenseEnemyKind;
  readonly x: number;
  readonly y: number;
  /** Volle Kantenlänge des gestorbenen Gegners – Maßstab für Leichen-Visuals. */
  readonly size: number;
  readonly faction: EnemyFaction;
  readonly ownerId?: string;
  /** Vollstaendige visuelle Identitaet des letzten sichtbaren Frames vor dem Destroy. */
  readonly textureKey: string;
  readonly frame: string;
  readonly displayWidth: number;
  readonly displayHeight: number;
  readonly rotation: number;
  readonly tint: number;
}

export interface EnemyLethalDamageContext {
  readonly id: string;
  readonly kind: CoopDefenseEnemyKind;
  readonly faction: EnemyFaction;
  readonly ownerId?: string;
  readonly maxHp: number;
}

export type EnemyLethalDamageDecision =
  | { readonly kind: 'allow-death' }
  | { readonly kind: 'rescue'; readonly healing: number };

/** A rescue decision may consume guard-owned charges, but cannot mutate Enemy HP. */
export type EnemyLethalDamageGuard = (
  enemy: Readonly<EnemyLethalDamageContext>,
) => EnemyLethalDamageDecision;

export interface EnemyDamageResult {
  readonly outcome: CombatDamageMutationOutcome;
  readonly died: boolean;
  readonly remainingHp: number;
  readonly death?: EnemyDeathInfo;
}

/**
 * Minimal-Schnittstelle des Gegner-Einbuddel-Systems für die Bewegung – als lokaler Typ gehalten,
 * damit der EnemyManager nicht auf das System zurück-importieren muss.
 */
export interface EnemyBurrowMovementSource {
  isBurrowed(enemyId: string): boolean;
  /** Erzwungene Grabrichtung während der Einbuddel-Anfahrt; null = normale Wegfindung. */
  getForcedDirection(enemyId: string): { x: number; y: number } | null;
  getSpeedFactor(enemyId: string): number;
}

/**
 * Minimal-Schnittstelle des Gefechtsabstand-Systems – strukturell erfüllt vom
 * CoopDefenseEnemyCombatPositioningSystem. Liefert für Fernkämpfer eine Wunschgeschwindigkeit,
 * die die Wegfindung ersetzt (Rückzug oder Stehenbleiben auf dem gewünschten Abstand).
 */
export interface EnemyCombatPositioningSource {
  getMovementOverride(enemyId: string): { vx: number; vy: number } | null;
}

/** Read-only combat decision, evaluated before ordinary movement without advancing weapons. */
export interface EnemyCombatMovementSource {
  getCombatMovement(enemy: EnemyEntity, now: number): { aimAngle: number; holdPosition: boolean; committed?: boolean } | null;
}

/** Exklusive Spezialbewegung, die normale KI-Zweige fuer diesen Frame ersetzt. */
export interface EnemySpecialMovementSource {
  getMovementOverride(enemy: EnemyEntity, now: number): { vx: number; vy: number } | null;
}

/**
 * Gegner-Visuals, die nicht an der Entity selbst hängen: Buddel-Partikel und der Spawn-Effekt.
 * Strukturell erfüllt vom EffectSystem, das dieselben Effekte für Spieler zeichnet – als lokaler
 * Typ gehalten, damit der EnemyManager nicht auf die Effekt-Schicht importieren muss.
 */
export interface EnemyVisualSink {
  /** `alliedColor` recolors claws of allied figures; hostile claws keep the shared danger color. */
  syncEnemyClaw?(id: string, state: import('../systems/EnemyClawAttack').EnemyClawState, x: number, y: number, now: number, visible: boolean, alliedColor?: number): void;
  clearEnemyClaw?(id: string): void;
  clearEnemyClawEffects?(): void;
  syncBurrowState(id: string, phase: BurrowPhase, sprite?: Phaser.GameObjects.Image): void;
  clearBurrowState(id: string): void;
  playBurrowPhaseEffect(x: number, y: number, phase: BurrowPhase): void;
  playEnemySpawnEffect(x: number, y: number, colorHex: number): void;
}

interface WildfirePanicState extends WildfireSourceInfo {
  directionX: number;
  directionY: number;
  lastTrailCellKey: string | null;
  lastTrailX: number;
  lastTrailY: number;
}

export interface EnemySpawnOptions {
  /** Spawn visual is represented by the burrow effect instead of the normal materialization burst. */
  readonly spawnBurrowed?: boolean;
  /** Authored edge for generic edge-burrow spawns; legacy callers default to west. */
  readonly spawnFront?: SpawnFront;
  /** Host-only generic provenance, e.g. the owning encounter id. */
  readonly originId?: string;
}

export class EnemyManager {
  private intents: EnemyIntentSystem | null = null;
  private readonly locomotion = new EnemyLocomotion();
  private readonly movementFeedback = new Map<string, MovementFeedback>();
  private movementNow = 0;
  setNavigationIntents(intents: EnemyIntentSystem | null): void { this.intents = intents; }
  getNavigationIntent(enemyId: string) { return this.intents?.get(enemyId) ?? null; }
  hasNavigationIntents(): boolean { return this.intents !== null; }
  isIntentTarget(enemyId: string, kind: string, id: string, explicitPlayerSideAction = false): boolean {
    if (!this.intents) return true;
    const intent = this.intents.get(enemyId);
    return (explicitPlayerSideAction && intent?.reason === 'siege')
      || (intent?.target?.kind === kind && intent.target.id === id);
  }
  getMovementFeedback(enemyId: string) { return this.movementFeedback.get(enemyId) ?? null; }
  getNavigationWorkCounters() { return { ...this.locomotion.getWorkCounters(), ...this.intents?.getWorkCounters() }; }
  getBreachAttackPoint(enemyId: string) { return this.intents?.getBreachAttackPoint(enemyId) ?? null; }
  routeAlly(enemy: EnemyEntity, key: string, destination: { x: number; y: number }, range: number) {
    return (enemy.faction === 'allied' ? this.intents?.routeAlly(enemy, key, destination, range)
      : this.intents?.routeTo(key, enemy.sprite.x, enemy.sprite.y, enemy.getSize() / 2, destination, range)) ?? null;
  }
  moveNormally(enemy: EnemyEntity, waypoint: { x: number; y: number } | null, speed: number,
    aimAngle?: number, priority: 'ordinary' | 'attack' = 'ordinary'): MovementFeedback {
    const previous = enemy.getDesiredVelocity();
    const navigation = this.intents?.get(enemy.id)?.navigation;
    const result = this.locomotion.solve({ id: enemy.id, x: enemy.sprite.x, y: enemy.sprite.y,
      radius: enemy.getSize() / 2, speed, waypoint, priority, previousVx: previous.vx, previousVy: previous.vy,
      routeCost: navigation?.status === 'ready' ? navigation.cost : undefined });
    this.movementFeedback.set(enemy.id, result);
    enemy.setDesiredVelocity(result.vx, result.vy, this.movementNow, aimAngle,
      result.waitReason === 'none' ? 'locomotion' : 'immediate');
    return result;
  }
  private readonly committedDeathWork = new WeakMap<CombatDamageMutationOutcome, (isCurrent: () => boolean) => void>();
  private combatActive = true;
  /** Distinguishes rebuilt Activity owners until P4 supplies the full World/Activity target binding. */
  private readonly combatScope: CombatScope = Object.freeze({
    worldRevision: 1,
    runtimeGeneration: nextEnemyCombatOwnerGeneration++,
  });
  private readonly enemyTargets = new Map<string, CombatTargetRef>();
  private readonly pendingClawEvents = new Map<string, import('../systems/EnemyClawAttack').EnemyClawEvent>();

  publishClawState(enemy: EnemyEntity, state: import('../systems/EnemyClawAttack').EnemyClawState): import('../systems/EnemyClawAttack').EnemyClawEvent | null {
    const generation = this.enemyTargets.get(enemy.id)?.instance.entityGeneration;
    if (generation === undefined || this.enemies.get(enemy.id) !== enemy) return null;
    enemy.applyClawAttackState(state);
    return { enemyId: enemy.id, entityGeneration: generation, state };
  }

  applyClawEvent(event: import('../systems/EnemyClawAttack').EnemyClawEvent): void {
    const generation = this.enemyTargets.get(event.enemyId)?.instance.entityGeneration;
    if (generation === event.entityGeneration) {
      this.enemies.get(event.enemyId)?.applyClawAttackState(event.state);
    } else if (generation === undefined || event.entityGeneration > generation) {
      const previous = this.pendingClawEvents.get(event.enemyId);
      if (previous && (previous.entityGeneration > event.entityGeneration
        || (previous.entityGeneration === event.entityGeneration && previous.state.revision >= event.state.revision))) return;
      if (this.pendingClawEvents.size >= 1024) this.pendingClawEvents.delete(this.pendingClawEvents.keys().next().value!);
      this.pendingClawEvents.set(event.enemyId, event);
    }
  }
  private nextEnemyGeneration = 1;
  private mutationOutcomeSequence = 0;
  private readonly scene: Phaser.Scene;
  private readonly resolvedConfigs: ResolvedCoopDefenseEnemyConfigs;
  private readonly enemies = new Map<string, EnemyEntity>();
  private readonly netSnapshotCache = new Map<string, SyncedEnemyState>();
  // id -> verbleibende Anzahl Delta-Snapshots, in denen die Removal noch mitgesendet wird.
  private readonly pendingRemovals = new Map<string, number>();
  private nextEnemyIdSeq = 1;
  // Sendet die aktive ID-Liste sofort beim ersten Snapshot (Bootstrap), danach periodisch.
  private ticksSinceActiveList = ENEMY_NET_ACTIVE_LIST_INTERVAL_TICKS;
  private forceFullNetSnapshot = false;
  private refreshCursor = 0;
  private readonly wildfirePanicStates = new Map<string, WildfirePanicState>();
  private plagueMovement: { getTarget(enemyId: string, now: number): { x: number; y: number; speedBonus: number } | null } | null = null;
  private readonly plaguePursuers = new Set<string>();
  setPlagueMovementSource(source: typeof this.plagueMovement): void {
    this.plagueMovement = source;
    this.plaguePursuers.clear();
  }
  isPursuingPlagueTarget(enemyId: string, now: number): boolean {
    const enemy = this.enemies.get(enemyId);
    return this.plaguePursuers.has(enemyId) && !!enemy && enemy.sprite.active && enemy.getHp() > 0
      && !enemy.isBurrowed() && enemy.getDashPhase() === 0 && !!this.plagueMovement?.getTarget(enemyId, now);
  }
  private smokePerception: SmokePerceptionPort | null = null;
  private smokeNow = 0;
  setSmokePerception(port: SmokePerceptionPort | null, now: number): void { this.smokePerception = port; this.smokeNow = now; }
  canSeeThroughSmoke(enemyId: string, x: number, y: number, range: number): boolean {
    const enemy = this.enemies.get(enemyId);
    if (!enemy || enemy.faction !== 'hostile' || !this.smokePerception) return true;
    return this.smokePerception.canSee(enemyId, enemy.sprite.x, enemy.sprite.y, x, y, range, this.smokeNow);
  }
  private readonly smokeConfusionStates = new Map<string, EnemySmokeConfusionState>();
  private onEnemySpawned: ((enemy: EnemyEntity, options?: EnemySpawnOptions) => void) | null = null;
  private onEnemyRemoving: ((enemy: EnemyEntity) => void) | null = null;
  setEnemyRemovingCallback(callback: ((enemy: EnemyEntity) => void) | null): void { this.onEnemyRemoving = callback; }
  private lethalDamageGuard: EnemyLethalDamageGuard | null = null;
  private visualSink: EnemyVisualSink | null = null;
  private lighting: LightingSystem | null = null;
  private healthBars: WorldHealthBarRenderer | null = null;
  private burnGpu: EntityBurnGpuController | null = null;
  private worldMetrics: WorldMetrics | null = null;
  /**
   * True, sobald der erste Snapshot verarbeitet wurde. Die Gegner daraus existieren beim Host
   * bereits seit Längerem – ein Client, der mitten in die Runde kommt, würde sonst für das
   * gesamte laufende Feld gleichzeitig Spawn-Effekte zünden.
   */
  private remoteSnapshotSeen = false;

  constructor(scene: Phaser.Scene, resolvedConfigs: ResolvedCoopDefenseEnemyConfigs = resolveCoopDefenseEnemyConfigs(1)) {
    this.scene = scene;
    this.resolvedConfigs = resolvedConfigs;
  }

  setHealthBarRenderer(renderer: WorldHealthBarRenderer | null): void {
    this.healthBars = renderer;
    for (const enemy of this.enemies.values()) enemy.setHealthBarRenderer(renderer);
  }

  setWorldMetrics(metrics: WorldMetrics): void {
    this.worldMetrics = metrics;
  }

  private waterGeometry: WaterGeometry | null = null;
  setWaterGeometry(water: WaterGeometry | null): void { this.waterGeometry = water; }

  /** Reicht die scene-lifetime Beleuchtung an neue und bestehende Gegner durch. */
  setLightingSystem(lighting: LightingSystem | null): void {
    this.lighting = lighting;
    for (const enemy of this.enemies.values()) enemy.setLightingSystem(lighting);
  }

  /** Reicht den scene-lifetime Brand-Partikelcontroller durch, genau wie die Beleuchtung. */
  setEntityBurnGpuController(controller: EntityBurnGpuController | null): void {
    this.burnGpu = controller;
    for (const enemy of this.enemies.values()) enemy.setEntityBurnGpuController(controller);
  }

  /**
   * Host-Callback fuer jeden neu erzeugten Gegner – unabhaengig davon, ob er aus einer Welle,
   * einem Death-Spawn oder einer Gegner-Faehigkeit stammt.
   */
  setEnemySpawnedCallback(callback: ((enemy: EnemyEntity, options?: EnemySpawnOptions) => void) | null): void {
    this.onEnemySpawned = callback;
  }

  /** Host-seitiger Wächter, der einen tödlichen Treffer abfangen darf. */
  setLethalDamageGuard(guard: EnemyLethalDamageGuard | null): void {
    this.lethalDamageGuard = guard;
  }

  /** Registriert die Effekt-Schicht für Buddel- und Spawn-Visuals (Host wie Client). */
  setVisualSink(sink: EnemyVisualSink | null): void {
    this.visualSink = sink;
  }

  /**
   * Einziger Weg, den Einbuddel-Zustand eines Gegners zu setzen – hier hängen die Buddel-Visuals
   * dran. Der Host ruft das aus dem Burrow-System, der Client beim Anwenden des Snapshots, so dass
   * beide Seiten dieselbe Darstellung wie bei eingebuddelten Spielern zeigen.
   */
  setEnemyBurrowed(enemyId: string, burrowed: boolean): void {
    const enemy = this.enemies.get(enemyId);
    if (!enemy || !enemy.setBurrowed(burrowed)) return;

    const sink = this.visualSink;
    if (!sink) return;
    sink.playBurrowPhaseEffect(enemy.sprite.x, enemy.sprite.y, burrowed ? 'windup' : 'recovery');
    if (burrowed) sink.syncBurrowState(enemyId, 'underground', enemy.sprite);
    else sink.clearBurrowState(enemyId);
  }

  hostSpawnDummyAt(
    gridX: number,
    gridY: number,
    kind: CoopDefenseEnemyKind = 'zombie-badger',
    options: EnemySpawnOptions = {},
  ): EnemyEntity {
    const world = this.gridToWorld(gridX, gridY);
    const x = world.x + Phaser.Math.RND.realInRange(-SPAWN_LANE_JITTER_PX, SPAWN_LANE_JITTER_PX);
    const y = world.y + Phaser.Math.RND.realInRange(-SPAWN_LANE_JITTER_PX, SPAWN_LANE_JITTER_PX);
    return this.hostSpawnAtWorld(x, y, kind, options);
  }

  hostSpawnAtWorld(
    x: number,
    y: number,
    kind: CoopDefenseEnemyKind,
    options: EnemySpawnOptions = {},
  ): EnemyEntity {
    return this.hostSpawnUnitAtWorld(x, y, kind, 'hostile', undefined, undefined, options);
  }

  hostSpawnAllyAtWorld(
    x: number,
    y: number,
    kind: CoopDefenseEnemyKind,
    ownerId: string,
    ownerColor: number,
    hpMultiplier: number,
  ): EnemyEntity {
    const enemy = this.hostSpawnUnitAtWorld(x, y, kind, 'allied', ownerId, ownerColor);
    const maxHp = Math.max(1, Math.round(enemy.getMaxHp() * Math.max(1, hpMultiplier)));
    enemy.setHp(maxHp, maxHp, true);
    return enemy;
  }

  private hostSpawnUnitAtWorld(
    x: number,
    y: number,
    kind: CoopDefenseEnemyKind,
    faction: EnemyFaction,
    ownerId?: string,
    ownerColor?: number,
    options: EnemySpawnOptions = {},
  ): EnemyEntity {
    if (this.waterGeometry) {
      const dry = this.waterGeometry.resolveDryPoint(x, y, this.resolvedConfigs[kind].size * .5);
      if (!dry) throw new Error('[EnemyManager] No dry ground available for enemy spawn');
      x = dry.x; y = dry.y;
    }
    const id = this.generateEnemyId(kind);
    const enemy = new EnemyEntity(
      this.scene,
      id,
      x,
      y,
      true,
      kind,
      this.resolvedConfigs[kind],
      faction,
      ownerId,
      ownerColor,
      options.originId,
    );
    enemy.setLightingSystem(this.lighting);
    enemy.setEntityBurnGpuController(this.burnGpu);
    enemy.setHealthBarRenderer(this.healthBars);
    this.enemies.set(id, enemy);
    this.registerCombatTarget(id, this.nextEnemyGeneration++);
    this.playSpawnEffect(enemy, options);
    this.onEnemySpawned?.(enemy, options);
    return enemy;
  }

  /**
   * Spawn-Effekt am Erscheinungsort. Host und Client zünden ihn jeweils lokal beim Anlegen der
   * Entity – derselbe Weg wie bei den Buddel-Visuals, also ohne eigenen Netzwerkpfad.
   *
   * Gegner, die eingebuddelt am Spielfeldrand starten, bleiben aussen vor: sie sind beim Spawn
   * unsichtbar, und ihr Auftauchen hat mit dem Buddel-Effekt bereits seine eigene Ankündigung.
   */
  private playSpawnEffect(enemy: EnemyEntity, options: EnemySpawnOptions): void {
    if (options.spawnBurrowed || this.resolvedConfigs[enemy.kind]?.burrow?.spawnBurrowedAtEdge) return;
    this.visualSink?.playEnemySpawnEffect(enemy.sprite.x, enemy.sprite.y, enemy.getSpawnEffectColor());
  }

  hostUpdateMovement(
    baseFlowFieldService: EnemyFlowFieldService | null,
    playerFlowFieldService: EnemyFlowFieldService | null,
    strategicFlowFieldService: EnemyFlowFieldService | null,
    bossFlowFieldService: EnemyFlowFieldService | null,
    movementLocked: boolean,
    now: number,
    deltaMs: number,
    fireSystem?: FireSystem | null,
    activeBurnSourceResolver?: ((enemyId: string, now: number) => ReadonlyArray<{ sourceKey: string }>) | null,
    trainAwarenessSystem?: CoopDefenseEnemyTrainAwarenessSystem | null,
    burrowSystem?: EnemyBurrowMovementSource | null,
    combatPositioningSystem?: EnemyCombatPositioningSource | null,
    specialMovementSource?: EnemySpecialMovementSource | null,
    smokeSystem?: SmokePerceptionPort | null,
    decoyTargets?: DecoyTargetPort | null,
    combatMovementSource?: EnemyCombatMovementSource | null,
  ): void {
    this.movementNow = now;
    this.plaguePursuers.clear();
    const lerpT = 1 - Math.exp(-STEER_RESPONSIVENESS * (deltaMs / 1000));
    this.movementFeedback.clear();
    const geometry = baseFlowFieldService?.getNavigationGeometry();
    if (geometry) this.locomotion.begin([...this.enemies.values()]
      .filter(enemy => enemy.sprite.active && !enemy.isBurrowed() && !burrowSystem?.isBurrowed(enemy.id)
        && (enemy.sprite.body as Phaser.Physics.Arcade.Body | null)?.enable !== false)
      .map(enemy => ({
      id: enemy.id, x: enemy.sprite.x, y: enemy.sprite.y, radius: enemy.getSize() / 2,
      ...enemy.getAppliedVelocity(),
      routeCost: this.intents?.get(enemy.id)?.navigation.status === 'ready'
        ? (this.intents.get(enemy.id)!.navigation as Extract<import('../systems/navigation/NavigationContracts').NavigationResult, { status: 'ready' }>).cost : undefined,
    })), geometry, deltaMs);
    // Basislose Vorstoss-Karten haben kein gueltiges Basisziel. Basisorientierte Gegner folgen
    // dann dem vorhandenen Spieler-Flowfield; eine zweite Navigation entsteht dabei nicht.
    const baseTargetFlowFieldService = baseFlowFieldService?.hasGoalCells() === false
      ? playerFlowFieldService ?? baseFlowFieldService
      : baseFlowFieldService;

    for (const enemy of this.enemies.values()) {
      if (enemy.faction === 'allied') continue;
      // Observational only. Obstacle damage requires a separate, current breach authorization.
      enemy.setPathBlocked(false);
      const config = this.resolvedConfigs[enemy.kind];
      const isBurrowed = burrowSystem?.isBurrowed(enemy.id) ?? false;
      const burrowSpeedFactor = isBurrowed ? (burrowSystem?.getSpeedFactor(enemy.id) ?? 1) : 1;
      // Unter der Erde ist der Zug keine Gefahr – die Gleis-KI bleibt dann komplett aussen vor.
      const activeTrainAwareness = isBurrowed ? null : trainAwarenessSystem;
      const decoyTarget = decoyTargets?.getTarget(enemy.id);
      const primaryFlowFieldService = decoyTarget ? decoyTargets?.getMovementField(enemy.id) ?? null
        : config.movementTarget === 'players-and-armed-constructs'
        ? strategicFlowFieldService ?? playerFlowFieldService ?? baseTargetFlowFieldService
        : config.isBoss
          ? bossFlowFieldService ?? baseTargetFlowFieldService
          : config.movementTarget === 'players'
          ? playerFlowFieldService ?? baseTargetFlowFieldService
          : baseTargetFlowFieldService;

      if (movementLocked) {
        enemy.stopMovement();
        continue;
      }

      // Einbuddel-Anfahrt: der Gegner graebt sich stur in die vorgegebene Richtung, bis das
      // Burrow-System ein freies Feld meldet. Wegfindung, Separation und Gleis-KI ruhen solange.
      const forcedBurrowDirection = burrowSystem?.getForcedDirection(enemy.id) ?? null;
      if (forcedBurrowDirection) {
        const burrowSpeed = enemy.getMoveSpeed() * burrowSpeedFactor;
        enemy.setDesiredVelocity(
          forcedBurrowDirection.x * burrowSpeed,
          forcedBurrowDirection.y * burrowSpeed,
          now,
        );
        continue;
      }

      const specialMovement = specialMovementSource?.getMovementOverride(enemy, now) ?? null;
      if (specialMovement) {
        enemy.setDesiredVelocity(specialMovement.vx, specialMovement.vy, now);
        continue;
      }

      const wildfirePanic = this.updateWildfirePanicState(
        enemy,
        fireSystem ?? null,
        activeBurnSourceResolver ?? null,
        now,
      );
      if (wildfirePanic) {
        const speed = enemy.getMoveSpeed() * wildfirePanic.speedMultiplier;
        const targetVx = wildfirePanic.directionX * speed;
        const targetVy = wildfirePanic.directionY * speed;
        const current = enemy.getDesiredVelocity();
        const decision = activeTrainAwareness?.resolveMovement(enemy, targetVx, targetVy, now);
        enemy.setDesiredVelocity(
          decision?.override ? decision.vx : Phaser.Math.Linear(current.vx, targetVx, lerpT),
          decision?.override ? decision.vy : Phaser.Math.Linear(current.vy, targetVy, lerpT),
          now,
        );
        continue;
      }

      if (!primaryFlowFieldService) {
        this.smokeConfusionStates.delete(enemy.id);
        enemy.stopMovement();
        continue;
      }

      // Angriffspause: Waffen ohne eigenen Bewegungsfaktor halten den Gegner wie bisher komplett
      // an. Waffen mit Faktor > 0 lassen ihn dagegen gebremst weiterlaufen – die Blickrichtung
      // bleibt dabei am Ziel, weil die Pause weiterhin aktiv ist.
      const specialAction = enemy.getSpecialAction() !== 'none';
      const combatMovement = specialAction ? null : combatMovementSource?.getCombatMovement(enemy, now) ?? null;
      if (combatMovement?.committed) {
        enemy.stopMovement();
        enemy.faceAngle(combatMovement.aimAngle);
        continue;
      }
      const attackMovementFactor = !combatMovementSource || combatMovement || specialAction
        ? enemy.getAttackMovementSpeedFactor(now) : 1;
      if (attackMovementFactor <= 0 && enemy.isAttackMovementPaused(now)) {
        const current = enemy.getDesiredVelocity();
        const trainDecision = activeTrainAwareness?.resolveMovement(enemy, current.vx, current.vy, now);
        if (trainDecision?.override && activeTrainAwareness?.blocksRegularAttacks(enemy.id)) {
          enemy.setDesiredVelocity(trainDecision.vx, trainDecision.vy, now);
        } else {
          enemy.stopMovement();
          if (combatMovement) enemy.faceAngle(combatMovement.aimAngle);
        }
        continue;
      }

      const infectionTarget = !config.isBoss && !decoyTarget && !smokeSystem?.getConfusion(enemy.id, now)
        ? this.plagueMovement?.getTarget(enemy.id, now) : null;
      if (infectionTarget) {
        const move = this.moveNormally(enemy, infectionTarget, enemy.getMoveSpeed() * attackMovementFactor * (1 + infectionTarget.speedBonus));
        if (move.vx || move.vy) this.plaguePursuers.add(enemy.id);
        continue;
      }

      // Gefechtsabstand: Fernkämpfer halten ihren Wunschabstand, statt der Wegfindung bis in den
      // Nahkampf zu folgen. Die Vorgabe greift erst hinter der Angriffspause, damit ein Gegner
      // während seines Schusses stehen bleibt.
      const positioningOverride = combatPositioningSystem?.getMovementOverride(enemy.id) ?? null;
      if (positioningOverride && !smokeSystem?.getConfusion(enemy.id, now)) {
        const decision = activeTrainAwareness?.resolveMovement(
          enemy,
          positioningOverride.vx,
          positioningOverride.vy,
          now,
        );
        if (!decision?.override && decoyTarget) decoyTargets?.usedTarget(enemy.id);
        if (decision?.override) enemy.setDesiredVelocity(decision.vx, decision.vy, now);
        else this.moveNormally(enemy, { x: enemy.sprite.x + positioningOverride.vx * 0.25,
          y: enemy.sprite.y + positioningOverride.vy * 0.25 },
          Math.hypot(positioningOverride.vx, positioningOverride.vy) * attackMovementFactor, combatMovement?.aimAngle);
        continue;
      }

      if (combatMovement?.holdPosition && !smokeSystem?.getConfusion(enemy.id, now)) {
        const train = activeTrainAwareness?.resolveMovement(enemy, 0, 0, now);
        if (train?.override) enemy.setDesiredVelocity(train.vx, train.vy, now);
        else this.moveNormally(enemy, null, 0, combatMovement.aimAngle, 'attack');
        continue;
      }

      const flowFieldService = this.intents?.getField(enemy.id) ?? primaryFlowFieldService;
      if (this.intents && !this.intents.get(enemy.id)) { enemy.stopMovement(); continue; }
      const route = this.intents?.get(enemy.id)?.navigation ?? flowFieldService.queryNavigation(enemy.sprite.x, enemy.sprite.y);
      enemy.setPathBlocked(route.status === 'unreachable' || route.status === 'invalid-start');
      let waypoint = route.status === 'ready' ? route.waypoint : route.status === 'pending' ? route.continuation ?? null : null;
      const gridCell = flowFieldService.worldToGrid(enemy.sprite.x, enemy.sprite.y);
      if (waypoint && gridCell) {
        const direction = this.normalizeDirection(waypoint.x - enemy.sprite.x, waypoint.y - enemy.sprite.y);
        const confused = resolveEnemySmokeConfusion(this.smokeConfusionStates, enemy.id, enemy.sprite.x, enemy.sprite.y,
          smokeSystem ?? null, flowFieldService, gridCell.gridX, gridCell.gridY, direction, now);
        if (confused) waypoint = { x: enemy.sprite.x + confused.x * 48, y: enemy.sprite.y + confused.y * 48 };
      }
      // Embedded starts use overlap-reducing local recovery, never an arbitrary reachable-cell jump.
      if (route.status === 'invalid-start') waypoint = { x: enemy.sprite.x + 1, y: enemy.sprite.y };
      const feedback = this.moveNormally(enemy, waypoint, enemy.getMoveSpeed() * burrowSpeedFactor * attackMovementFactor,
        combatMovement?.aimAngle);
      const train = activeTrainAwareness?.resolveMovement(enemy, feedback.vx, feedback.vy, now);
      if (train?.override) enemy.setDesiredVelocity(train.vx, train.vy, now);
      else if (decoyTarget && route.status === 'ready') decoyTargets?.usedTarget(enemy.id);
    }
  }
  private captureWildfireDeath(enemyId: string): import('../types').MolotovWildfireDeath | undefined {
    const state = this.wildfirePanicStates.get(enemyId);
    if (!state?.deathBurst) return undefined;
    return { sourceKey: state.sourceId, ownerId: state.ownerId, burst: { ...state.deathBurst } };
  }

  isEnemyPanicking(enemyId: string): boolean {
    return this.wildfirePanicStates.has(enemyId);
  }

  private updateWildfirePanicState(
    enemy: EnemyEntity,
    fireSystem: FireSystem | null,
    activeBurnSourceResolver: ((enemyId: string, now: number) => ReadonlyArray<{ sourceKey: string }>) | null,
    now: number,
  ): WildfirePanicState | null {
    if (!fireSystem || !activeBurnSourceResolver) {
      this.wildfirePanicStates.delete(enemy.id);
      return null;
    }

    const activeBurns = activeBurnSourceResolver(enemy.id, now);
    const activeSourceIds = new Set(activeBurns.map(source => source.sourceKey));
    let state = this.wildfirePanicStates.get(enemy.id) ?? null;
    if (state && !activeSourceIds.has(state.sourceId)) {
      this.wildfirePanicStates.delete(enemy.id);
      state = null;
    }

    if (!state) {
      const candidates = [...activeSourceIds].sort();
      for (const sourceId of candidates) {
        const info = fireSystem.getWildfireSourceInfo(sourceId);
        const direction = fireSystem.getWildfireEscapeVector(
          sourceId,
          enemy.sprite.x,
          enemy.sprite.y,
          enemy.getCollisionRadius(),
        );
        if (!info || !direction) continue;
        state = {
          ...info,
          directionX: direction.x,
          directionY: direction.y,
          lastTrailCellKey: null,
          lastTrailX: enemy.sprite.x,
          lastTrailY: enemy.sprite.y,
        };
        this.wildfirePanicStates.set(enemy.id, state);
        break;
      }
    }
    if (!state) return null;

    const updatedDirection = fireSystem.getWildfireEscapeVector(
      state.sourceId,
      enemy.sprite.x,
      enemy.sprite.y,
      enemy.getCollisionRadius(),
    );
    if (updatedDirection) {
      state.directionX = updatedDirection.x;
      state.directionY = updatedDirection.y;
    }

    const trailGridX = Math.floor(enemy.sprite.x / GROUND_FIRE_CELL_SIZE);
    const trailGridY = Math.floor(enemy.sprite.y / GROUND_FIRE_CELL_SIZE);
    const trailCellKey = `${trailGridX}:${trailGridY}`;
    if (state.trailDurationMs > 0 && trailCellKey !== state.lastTrailCellKey) {
      state.lastTrailCellKey = trailCellKey;
      fireSystem.hostRefreshGroundCellsAlongSegment(
        state.lastTrailX,
        state.lastTrailY,
        enemy.sprite.x,
        enemy.sprite.y,
        {
          // Pro Besitzer und Rasterzelle teilen sich alle Gegner eine auffrischbare
          // Quelle. So waechst die Feuerspur mit belegten Zellen statt mit der
          // Anzahl Gegner und bleibt auch bei grossen Horden begrenzt.
          sourceKey: `wildfire-trail:${state.ownerId}`,
          ownerId: state.ownerId,
          durationMs: state.trailDurationMs,
          damagePerTick: state.trailDamagePerTick,
          burn: state.burn,
          sourceId: 'ground_fire.wildfire',
          firewalker: state.firewalker,
        },
        now,
      );
      state.lastTrailX = enemy.sprite.x;
      state.lastTrailY = enemy.sprite.y;
    }

    return state;
  }

  private normalizeDirection(x: number, y: number): { x: number; y: number } {
    const length = Math.hypot(x, y);
    if (length <= 0.001) return { x: 0, y: 0 };
    return { x: x / length, y: y / length };
  }

  getNetSnapshot(): SyncedEnemySnapshot {
    // Kein schwerer Full-Snapshot mehr: Neue/geänderte Gegner gehen als Delta, unveränderte Gegner
    // werden rollierend (Refresh-Zyklus) binnen ~2 s einmal voll nachgesendet. Periodisch trägt der
    // Snapshot zusätzlich die vollständige aktive ID-Liste zur Phantom-Reconciliation.
    const sendActiveList = this.forceFullNetSnapshot
      || this.ticksSinceActiveList >= ENEMY_NET_ACTIVE_LIST_INTERVAL_TICKS;
    const currentIds = new Set<string>();
    const upserts: SyncedEnemyDeltaState[] = [];

    const sortedEnemies = [...this.enemies.values()]
      .sort((left, right) => left.id.localeCompare(right.id));
    const refreshIds = this.collectRefreshIds(sortedEnemies);

    for (const enemy of sortedEnemies) {
      const current = this.buildNetState(enemy);
      currentIds.add(current.id);
      const previous = this.netSnapshotCache.get(current.id);

      if (this.forceFullNetSnapshot) {
        upserts.push(current);
        this.netSnapshotCache.set(current.id, current);
        continue;
      }

      if (!previous) {
        upserts.push(current);
        this.netSnapshotCache.set(current.id, current);
        continue;
      }

      const delta = this.buildDeltaState(previous, current);
      if (delta) {
        upserts.push(delta);
        this.netSnapshotCache.set(current.id, {
          ...previous,
          ...delta,
        });
        continue;
      }

      if (!refreshIds.has(current.id)) continue;

      upserts.push(current);
      this.netSnapshotCache.set(current.id, current);
    }

    // Removals werden über mehrere Delta-Snapshots wiederholt (siehe ENEMY_NET_REMOVAL_RESEND_TICKS),
    // damit ein verlorenes unreliable-Paket nicht zu dauerhaft sichtbaren toten Gegnern führt.
    const removals = [...this.pendingRemovals.keys()].sort();
    for (const id of removals) {
      const remaining = (this.pendingRemovals.get(id) ?? 1) - 1;
      if (remaining <= 0) {
        this.pendingRemovals.delete(id);
      } else {
        this.pendingRemovals.set(id, remaining);
      }
    }

    const encodedUpserts: Array<number | string> = [];
    for (const entry of upserts) {
      encodeEnemyUpsert(encodedUpserts, entry);
    }

    const snapshot: SyncedEnemySnapshot = {
      c: currentIds.size,
      u: encodedUpserts,
      r: removals.map(enemyIdToNum),
    };

    if (sendActiveList) {
      // Cache-Einträge entfernter Gegner aufräumen und die aktive ID-Liste als Reconciliation-Backstop
      // anhängen. Der Client löscht lokal jeden Gegner, dessen ID hier fehlt (Phantom-Bereinigung).
      for (const id of [...this.netSnapshotCache.keys()]) {
        if (!currentIds.has(id)) this.netSnapshotCache.delete(id);
      }
      snapshot.a = [...currentIds].map(enemyIdToNum).sort((left, right) => left - right);
      this.ticksSinceActiveList = 0;
      this.forceFullNetSnapshot = false;
    } else {
      this.ticksSinceActiveList += 1;
    }

    return snapshot;
  }

  getEnemy(id: string): EnemyEntity | undefined {
    return this.enemies.get(id);
  }

  /** Allokationsfreie Iteration fuer Host-Systeme im engen Frame-Hotpath. */
  forEachEnemy(visitor: (enemy: EnemyEntity) => void): void {
    for (const enemy of this.enemies.values()) visitor(enemy);
  }

  getAllEnemies(): EnemyEntity[] {
    return [...this.enemies.values()];
  }

  /** Naechster Netzwerk-Snapshot enthaelt jeden aktuellen Gegner vollstaendig. */
  requestFullNetSnapshot(): void {
    this.forceFullNetSnapshot = true;
  }

  /**
   * Höchste aktive Bossphase im Feld. Ohne Allokation, weil das pro Frame für die
   * Bildkomposition abgefragt wird.
   */
  getMaxBossPhase(): number {
    let phase = 0;
    for (const enemy of this.enemies.values()) {
      const enemyPhase = enemy.getBossPhase();
      if (enemyPhase > phase) phase = enemyPhase;
    }
    return phase;
  }

  getHostileEnemies(): EnemyEntity[] {
    return [...this.enemies.values()].filter((enemy) => enemy.faction === 'hostile');
  }

  getAlliedEnemies(ownerId?: string): EnemyEntity[] {
    return [...this.enemies.values()].filter((enemy) => enemy.faction === 'allied' && (ownerId === undefined || enemy.ownerId === ownerId));
  }

  hasActiveEnemyOrigin(originId: string): boolean {
    return this.getActiveEnemyIdsForOrigin(originId).length > 0;
  }

  getActiveEnemyIdsForOrigin(originId: string): string[] {
    return [...this.enemies.values()]
      .filter((enemy) => enemy.faction === 'hostile' && enemy.sprite.active && enemy.originId === originId)
      .map((enemy) => enemy.id);
  }

  hasEnemy(id: string): boolean {
    return this.enemies.has(id);
  }

  hasEnemyKind(kind: CoopDefenseEnemyKind): boolean {
    for (const enemy of this.enemies.values()) {
      if (enemy.faction === 'hostile' && enemy.kind === kind) return true;
    }
    return false;
  }

  /** Host-only: autoritative Entfernung ohne Killbelohnung, Todeseffekt oder Death-Spawns. */
  hostRemoveWithoutKill(id: string): EnemyDeathInfo | null {
    const enemy = this.enemies.get(id);
    if (!enemy) return null;
    const visual = captureEnemyDeathVisual(enemy);
    const death: EnemyDeathInfo = {
      id: enemy.id,
      kind: enemy.kind,
      x: enemy.sprite.x,
      y: enemy.sprite.y,
      size: enemy.getSize(),
      faction: enemy.faction,
      ownerId: enemy.ownerId,
      ...visual,
    };
    this.pendingRemovals.set(id, ENEMY_NET_REMOVAL_RESEND_TICKS);
    this.netSnapshotCache.delete(id);
    this.destroyEnemyEntity(id, enemy);
    this.wildfirePanicStates.delete(id);
    this.smokeConfusionStates.delete(id);
    return death;
  }

  getCombatTargetRef(id: string): CombatTargetRef | null {
    return this.enemyTargets.get(id) ?? null;
  }

  private registerCombatTarget(id: string, generation: number): void {
    this.enemyTargets.set(id, Object.freeze({
      kind: 'enemy' as const,
      id,
      scope: this.combatScope,
      instance: Object.freeze({ entityGeneration: generation }),
    }));
  }

  commitDamage(request: TargetDamageMutationRequest): CombatDamageMutationOutcome {
    return this.commitDamageInternal(request).outcome;
  }

  readCombatVitals(target: CombatTargetRef): CombatantVitalsSnapshot | null {
    if (target.kind !== 'enemy') return null;
    const current = this.getCombatTargetRef(target.id);
    const enemy = this.enemies.get(target.id);
    return current && enemy && isSameCombatTargetInstance(current, target)
      ? this.enemyVitals(enemy, enemy.getHp() > 0) : null;
  }

  commitSupport(request: TargetSupportMutationRequest): CombatSupportMutationOutcome {
    if (!isSameCombatScope(request.target.scope, this.combatScope)) {
      return freezeTargetMutationOutcome({
        kind: 'rejected', outcomeId: request.outcomeId, target: request.target,
        source: request.source, reason: 'stale-scope',
      });
    }
    const enemy = request.target.kind === 'enemy' ? this.enemies.get(request.target.id) : undefined;
    const currentTarget = request.target.kind === 'enemy' ? this.getCombatTargetRef(request.target.id) : null;
    if (!enemy || !currentTarget) {
      return freezeTargetMutationOutcome({
        kind: 'rejected', outcomeId: request.outcomeId, target: request.target,
        source: request.source, reason: 'target-missing',
      });
    }
    if (!isSameCombatTargetInstance(request.target, currentTarget)) {
      return freezeTargetMutationOutcome({
        kind: 'rejected', outcomeId: request.outcomeId, target: request.target,
        source: request.source, reason: 'stale-target',
      });
    }
    if (enemy.getHp() <= 0) {
      return freezeTargetMutationOutcome({
        kind: 'rejected', outcomeId: request.outcomeId, target: request.target,
        source: request.source, reason: 'target-dead',
      });
    }
    if (request.supportKind !== 'heal' && request.supportKind !== 'hp-regeneration') {
      return freezeTargetMutationOutcome({
        kind: 'rejected', outcomeId: request.outcomeId, target: request.target,
        source: request.source, reason: 'not-eligible',
      });
    }
    if (!Number.isFinite(request.amount) || request.amount < 0) {
      return freezeTargetMutationOutcome({
        kind: 'rejected', outcomeId: request.outcomeId, target: request.target,
        source: request.source, reason: 'invalid-value',
      });
    }
    const before = enemy.getHp();
    const next = Math.min(enemy.getMaxHp(), before + request.amount);
    if (next === before) {
      return freezeTargetMutationOutcome({
        kind: 'accepted-no-effect', outcomeId: request.outcomeId, target: request.target,
        source: request.source, reason: 'zero-effect', resultingState: this.enemyVitals(enemy, true),
      });
    }
    enemy.setHp(next);
    return freezeTargetMutationOutcome({
      kind: 'support-applied', outcomeId: request.outcomeId, target: request.target,
      source: request.source, supportKind: request.supportKind, actualAmount: next - before,
      resultingState: this.enemyVitals(enemy, true), revived: false,
    });
  }

  applyHealing(id: string, amount: number, kind: 'heal' | 'hp-regeneration' = 'heal'): CombatSupportMutationOutcome | null {
    const target = this.getCombatTargetRef(id);
    if (!target) return null;
    return this.commitSupport({
      outcomeId: `legacy:enemy-support:${id}:${++this.mutationOutcomeSequence}`,
      target,
      source: {
        gameplaySource: { kind: 'environment', id: 'legacy-support' },
        attribution: { kind: 'world', id: 'legacy-support' },
        allegiance: { ownerId: 'world' },
        origin: 'support',
      },
      supportKind: kind,
      amount,
    });
  }

  /** Debug/initialization adapter; runtime combat healing must use applyHealing. */
  hostSetVitalsBaseline(id: string, hp: number, maxHp: number): boolean {
    const enemy = this.enemies.get(id);
    if (!enemy || !Number.isFinite(hp) || !Number.isFinite(maxHp) || maxHp <= 0) return false;
    const cappedMax = Math.max(1, maxHp);
    enemy.setHp(Math.min(cappedMax, Math.max(0, hp)), cappedMax, true);
    return true;
  }

  applyDamage(id: string, damage: number): EnemyDamageResult | null {
    const enemy = this.enemies.get(id);
    const target = this.getCombatTargetRef(id);
    if (!enemy || !target) return null;
    const result = this.commitDamageInternal({
      outcomeId: `legacy:enemy:${id}:${++this.mutationOutcomeSequence}`,
      target,
      source: {
        gameplaySource: { kind: 'environment', id: 'legacy-combat' },
        attribution: { kind: 'world', id: 'legacy-combat' },
        allegiance: { ownerId: 'world' },
        origin: 'direct',
      },
      damage: {
        amount: damage,
        damageKind: 'direct',
        basis: { kind: 'authored', amount: damage },
        sourceFactors: [],
        targetFactors: [],
        isCritical: false,
      },
    });
    this.completeCombatDeath(result.outcome);
    return result;
  }

  /** Runs death spawns only after the receipt has escaped the canonical mutation. */
  completeCombatDeath(outcome: CombatDamageMutationOutcome, isScopeCurrent?: () => boolean): void {
    const work = this.committedDeathWork.get(outcome);
    this.committedDeathWork.delete(outcome);
    const isCurrent = () => this.combatActive && (isScopeCurrent?.() ?? true);
    if (isCurrent()) work?.(isCurrent);
  }

  private commitDamageInternal(request: TargetDamageMutationRequest): EnemyDamageResult {
    if (!this.combatActive) return this.rejectedEnemyDamage(request, 'stale-scope');
    const enemy = request.target.kind === 'enemy' ? this.enemies.get(request.target.id) : undefined;
    const currentTarget = request.target.kind === 'enemy' ? this.getCombatTargetRef(request.target.id) : null;
    if (!isSameCombatScope(request.target.scope, this.combatScope)) {
      return this.rejectedEnemyDamage(request, 'stale-scope');
    }
    if (!enemy || !currentTarget) return this.rejectedEnemyDamage(request, 'target-missing');
    const id = enemy.id;
    if (!isSameCombatTargetInstance(request.target, currentTarget)) {
      return this.rejectedEnemyDamage(request, 'stale-target');
    }
    const damage = request.damage.amount;
    if (!Number.isFinite(damage) || damage < 0) return this.rejectedEnemyDamage(request, 'invalid-value');
    if (damage === 0) {
      return {
        outcome: freezeTargetMutationOutcome({
          kind: 'accepted-no-effect', outcomeId: request.outcomeId, target: request.target,
          source: request.source, reason: 'zero-effect',
          resultingState: this.enemyVitals(enemy, true),
        }),
        died: false,
        remainingHp: enemy.getHp(),
      };
    }

    const hpLost = Math.min(enemy.getHp(), damage);
    const remainingHp = enemy.getHp() - hpLost;
    enemy.setHp(remainingHp);
    if (remainingHp > 0) {
      return {
        outcome: freezeTargetMutationOutcome({
          kind: 'damage-applied', outcomeId: request.outcomeId, target: request.target,
          source: request.source, damage: request.damage, actualDamage: hpLost,
          hpLost, armorLost: 0, integrityLost: 0,
          resultingState: this.enemyVitals(enemy, true), transition: { kind: 'none' }, rescueHealing: 0,
        }),
        died: false,
        remainingHp,
      };
    }

    const decision = this.lethalDamageGuard?.({
      id: enemy.id,
      kind: enemy.kind,
      faction: enemy.faction,
      ownerId: enemy.ownerId,
      maxHp: enemy.getMaxHp(),
    }) ?? { kind: 'allow-death' as const };
    if (decision.kind === 'rescue') {
      const rescueHealing = Number.isFinite(decision.healing)
        ? Math.min(enemy.getMaxHp(), Math.max(0, decision.healing))
        : 0;
      if (rescueHealing > 0) {
        enemy.setHp(rescueHealing);
        return {
          outcome: freezeTargetMutationOutcome({
            kind: 'damage-applied', outcomeId: request.outcomeId, target: request.target,
            source: request.source, damage: request.damage, actualDamage: hpLost,
            hpLost, armorLost: 0, integrityLost: 0,
            resultingState: this.enemyVitals(enemy, true), transition: { kind: 'none' }, rescueHealing,
          }),
          died: false,
          // Legacy consumers used zero to preserve actual lethal damage despite the rescue.
          remainingHp: 0,
        };
      }
    }

    const visual = captureEnemyDeathVisual(enemy);
    const deathX = enemy.sprite.x;
    const deathY = enemy.sprite.y;
    const death: EnemyDeathInfo = {
      id: enemy.id,
      kind: enemy.kind,
      x: deathX,
      y: deathY,
      size: enemy.getSize(),
      faction: enemy.faction,
      ownerId: enemy.ownerId,
      ...visual,
    };
    const deathSpawns = enemy.faction === 'hostile' ? (this.resolvedConfigs[enemy.kind].deathSpawns ?? []) : [];
    const outcome = freezeTargetMutationOutcome({
      kind: 'damage-applied', outcomeId: request.outcomeId, target: request.target,
      source: request.source, damage: request.damage, actualDamage: hpLost,
      hpLost, armorLost: 0, integrityLost: 0,
      resultingState: this.enemyVitals(enemy, false),
      transition: {
        kind: 'dead',
        facts: {
          target: request.target,
          position: { x: death.x, y: death.y },
          targetAllegiance: enemy.ownerId ? { ownerId: enemy.ownerId, factionId: enemy.faction } : undefined,
          targetCategory: enemy.kind,
          rewardEligible: enemy.faction === 'hostile',
          molotovWildfire: this.captureWildfireDeath(id),
          presentation: { ...death },
        },
      },
    });
    this.pendingRemovals.set(id, ENEMY_NET_REMOVAL_RESEND_TICKS);
    this.netSnapshotCache.delete(id);
    this.destroyEnemyEntity(id, enemy);
    this.wildfirePanicStates.delete(id);
    this.smokeConfusionStates.delete(id);
    const originId = enemy.originId;
    this.committedDeathWork.set(outcome, isCurrent => {
      for (const spawnConfig of deathSpawns) {
        const baseAngle = Phaser.Math.RND.realInRange(0, Math.PI * 2);
        for (let index = 0; index < spawnConfig.count; index += 1) {
          const angle = baseAngle + index * (Math.PI * 2 / Math.max(1, spawnConfig.count));
          this.hostSpawnAtWorld(
            deathX + Math.cos(angle) * spawnConfig.offsetPx,
            deathY + Math.sin(angle) * spawnConfig.offsetPx,
            spawnConfig.enemyKind,
            { originId },
          );
          // A spawn hook may end the owner or its enclosing Combat scope mid-batch.
          if (!isCurrent()) return;
        }
      }
    });
    return { outcome, died: true, remainingHp: 0, death };
  }

  private rejectedEnemyDamage(
    request: TargetDamageMutationRequest,
    reason: 'stale-scope' | 'stale-target' | 'target-missing' | 'invalid-value',
  ): EnemyDamageResult {
    return {
      outcome: freezeTargetMutationOutcome({
        kind: 'rejected', outcomeId: request.outcomeId, target: request.target,
        source: request.source, reason,
      }),
      died: false,
      remainingHp: 0,
    };
  }

  private enemyVitals(enemy: EnemyEntity, alive: boolean) {
    return Object.freeze({
      kind: 'combatant' as const,
      hp: enemy.getHp(),
      maxHp: enemy.getMaxHp(),
      armor: 0,
      maxArmor: 0,
      alive,
    });
  }

  hostRemoveEnemy(id: string): void {
    const enemy = this.enemies.get(id);
    if (!enemy) return;
    this.pendingRemovals.set(id, ENEMY_NET_REMOVAL_RESEND_TICKS);
    this.netSnapshotCache.delete(id);
    this.destroyEnemyEntity(id, enemy);
    this.wildfirePanicStates.delete(id);
  }

  /**
   * Entfernt einen Gegner samt seiner Buddel-Partikel. Die Emitter folgen dem Sprite, deshalb
   * müssen sie vor dessen Zerstörung abgeräumt werden.
   */
  private destroyEnemyEntity(id: string, enemy: EnemyEntity): void {
    this.onEnemyRemoving?.(enemy);
    this.visualSink?.clearEnemyClaw?.(id);
    this.plaguePursuers.delete(id);
    this.visualSink?.clearBurrowState(id);
    enemy.destroy();
    this.enemies.delete(id);
    this.enemyTargets.delete(id);
  }

  syncHostVisuals(deltaMs: number, now: number): void {
    for (const enemy of this.enemies.values()) {
      enemy.syncMovementFacing(deltaMs);
      this.syncClawVisuals(enemy, now);
      enemy.syncBar();
    }
  }

  private syncClawVisuals(enemy: EnemyEntity, now: number): void {
    enemy.syncClawAnimation(now);
    this.visualSink?.syncEnemyClaw?.(enemy.id, enemy.getClawAttackState(), enemy.sprite.x, enemy.sprite.y, now,
      enemy.sprite.visible && !enemy.isBurrowed() && enemy.getHp() > 0,
      enemy.faction === 'allied' ? enemy.getSpawnEffectColor() : undefined);
  }

  applySnapshot(snapshot: SyncedEnemySnapshot | null): void {
    if (!snapshot) return;

    const upserts = decodeEnemyUpserts(snapshot.u);

    // Periodische Reconciliation: liegt die vollständige aktive ID-Liste vor, lösche jeden lokalen
    // Gegner, dessen ID darin fehlt (Backstop gegen verpasste Removals = "Phantom"-Gegner).
    if (snapshot.a) {
      const activeIds = new Set(snapshot.a);
      for (const [id, enemy] of this.enemies) {
        if (activeIds.has(enemyIdToNum(id))) continue;
        this.destroyEnemyEntity(id, enemy);
      }
    }

    for (const idNum of snapshot.r) {
      const id = enemyNumToId(idNum);
      const enemy = this.enemies.get(id);
      if (!enemy) continue;
      this.destroyEnemyEntity(id, enemy);
    }

    for (const remote of upserts) {
      this.applyRemoteSnapshot(remote);
    }
    this.remoteSnapshotSeen = true;
  }

  updateClientInterpolation(factor: number, now: number): void {
    for (const enemy of this.enemies.values()) {
      // Vor dem Interpolationsschritt: der noch offene Weg zur Zielposition ist auf dem Client
      // das Bewegungssignal fuer die Laufanimation.
      enemy.syncWalkingFromInterpolation();
      enemy.lerpStep(factor);
      this.syncClawVisuals(enemy, now);
    }
  }

  destroy(): void {
    this.pendingClawEvents.clear();
    this.locomotion.clear(); this.movementFeedback.clear(); this.intents = null;
    this.waterGeometry = null;
    this.combatActive = false;
    this.plagueMovement = null;
    this.plaguePursuers.clear();
    for (const [id, enemy] of this.enemies) {
      this.onEnemyRemoving?.(enemy);
      this.visualSink?.clearEnemyClaw?.(id);
      this.visualSink?.clearBurrowState(id);
      enemy.destroy();
    }
    this.enemies.clear();
    this.onEnemyRemoving = null;
    this.visualSink?.clearEnemyClawEffects?.();
    this.enemyTargets.clear();
    this.wildfirePanicStates.clear();
    this.smokeConfusionStates.clear();
    this.netSnapshotCache.clear();
    this.pendingRemovals.clear();
    this.nextEnemyIdSeq = 1;
    this.remoteSnapshotSeen = false;
    this.ticksSinceActiveList = ENEMY_NET_ACTIVE_LIST_INTERVAL_TICKS;
    this.forceFullNetSnapshot = false;
    this.refreshCursor = 0;
  }

  private collectRefreshIds(sortedEnemies: EnemyEntity[]): Set<string> {
    if (sortedEnemies.length === 0) {
      this.refreshCursor = 0;
      return new Set<string>();
    }

    const refreshCount = Math.max(1, Math.ceil(sortedEnemies.length / ENEMY_NET_REFRESH_CYCLE_TICKS));
    const ids = new Set<string>();

    for (let offset = 0; offset < refreshCount; offset += 1) {
      const enemy = sortedEnemies[(this.refreshCursor + offset) % sortedEnemies.length];
      ids.add(enemy.id);
    }

    this.refreshCursor = (this.refreshCursor + refreshCount) % sortedEnemies.length;
    return ids;
  }

  private buildNetState(enemy: EnemyEntity): SyncedEnemyState {
    const snapshot = enemy.getNetSnapshot();
    return {
      ...snapshot,
      entityGeneration: this.enemyTargets.get(enemy.id)?.instance.entityGeneration,
      x: Math.round(snapshot.x),
      y: Math.round(snapshot.y),
      rot: Math.round(snapshot.rot * 100) / 100,
      faction: snapshot.faction,
      burrowed: snapshot.burrowed,
      dashPhase: snapshot.dashPhase,
      specialAction: snapshot.specialAction,
      specialActionEndsAt: snapshot.specialActionEndsAt,
      gaussChargeProgress: Math.round(snapshot.gaussChargeProgress * 1000) / 1000,
      gaussAimAngle: Math.round(snapshot.gaussAimAngle * 100) / 100,
      ownerId: snapshot.ownerId,
      ownerColor: snapshot.ownerColor,
    };
  }

  private buildDeltaState(previous: SyncedEnemyState, current: SyncedEnemyState): SyncedEnemyDeltaState | null {
    const delta: SyncedEnemyDeltaState = { id: current.id };
    if (current.claw?.revision !== previous.claw?.revision) {
      delta.claw = current.claw;
      delta.entityGeneration = current.entityGeneration;
    }
    if (current.entityGeneration !== previous.entityGeneration) delta.entityGeneration = current.entityGeneration;
    if (current.positionRevision !== previous.positionRevision) {
      delta.positionRevision = current.positionRevision;
      delta.x = current.x;
      delta.y = current.y;
    }

    if (current.kind !== previous.kind) {
      delta.kind = current.kind;
    }

    if (
      Math.abs(current.x - previous.x) >= ENEMY_NET_POSITION_DELTA_PX
      || Math.abs(current.y - previous.y) >= ENEMY_NET_POSITION_DELTA_PX
    ) {
      delta.x = current.x;
      delta.y = current.y;
    }

    if (Math.abs(Phaser.Math.Angle.Wrap(current.rot - previous.rot)) >= ENEMY_NET_ROTATION_DELTA_RAD) {
      delta.rot = current.rot;
    }

    if (current.hp !== previous.hp || current.maxHp !== previous.maxHp) {
      delta.hp = current.hp;
      delta.maxHp = current.maxHp;
    }

    if (
      current.burnStacks !== previous.burnStacks
      || current.burnVisualStyle !== previous.burnVisualStyle
    ) {
      delta.burnStacks = current.burnStacks;
      delta.burnVisualStyle = current.burnVisualStyle;
    }
    if ((current.plasmaChargeStacks ?? 0) !== (previous.plasmaChargeStacks ?? 0)) {
      delta.plasmaChargeStacks = current.plasmaChargeStacks ?? 0;
    }
    if (current.faction !== previous.faction || current.ownerId !== previous.ownerId || current.ownerColor !== previous.ownerColor) {
      delta.faction = current.faction;
      delta.ownerId = current.ownerId;
      delta.ownerColor = current.ownerColor;
    }

    if (current.burrowed !== previous.burrowed) {
      delta.burrowed = current.burrowed;
    }

    if (current.dashPhase !== previous.dashPhase) {
      delta.dashPhase = current.dashPhase;
    }
    if (
      current.specialAction !== previous.specialAction
      || current.specialActionEndsAt !== previous.specialActionEndsAt
      || current.gaussChargeProgress !== previous.gaussChargeProgress
      || current.gaussAimAngle !== previous.gaussAimAngle
    ) {
      delta.specialAction = current.specialAction;
      delta.specialActionEndsAt = current.specialActionEndsAt;
      delta.gaussChargeProgress = current.gaussChargeProgress;
      delta.gaussAimAngle = current.gaussAimAngle;
    }

    return Object.keys(delta).length > 1 ? delta : null;
  }

  private applyRemoteSnapshot(remote: SyncedEnemyDeltaState): void {
    let enemy = this.enemies.get(remote.id);
    const currentGeneration = this.enemyTargets.get(remote.id)?.instance.entityGeneration;
    if (currentGeneration !== undefined && remote.entityGeneration !== undefined && remote.entityGeneration < currentGeneration) return;
    if (enemy && remote.entityGeneration !== undefined && remote.entityGeneration !== this.enemyTargets.get(remote.id)?.instance.entityGeneration) {
      this.destroyEnemyEntity(remote.id, enemy); enemy = undefined;
    }
    if (!enemy) {
      if (remote.kind === undefined || remote.x === undefined || remote.y === undefined) return;
      enemy = new EnemyEntity(
        this.scene,
        remote.id,
        remote.x,
        remote.y,
        false,
        remote.kind,
        this.resolvedConfigs[remote.kind],
        remote.faction ?? 'hostile',
        remote.ownerId,
        remote.ownerColor,
      );
      enemy.setLightingSystem(this.lighting);
      enemy.setEntityBurnGpuController(this.burnGpu);
      enemy.setHealthBarRenderer(this.healthBars);
      const rotation = remote.rot ?? 0;
      enemy.faceAngle(rotation);
      enemy.setTargetRotation(rotation);
      enemy.setHp(remote.hp ?? remote.maxHp ?? 1, remote.maxHp ?? remote.hp ?? 1, true);
      enemy.updateBurnStacks(remote.burnStacks ?? 0, remote.burnVisualStyle ?? 'normal');
      enemy.updatePlasmaChargeStacks(remote.plasmaChargeStacks ?? 0);
      enemy.setDashPhase(remote.dashPhase ?? 0);
      enemy.setSpecialAction(
        remote.specialAction ?? 'none',
        remote.specialActionEndsAt ?? 0,
        remote.gaussChargeProgress ?? 0,
        remote.gaussAimAngle ?? rotation,
      );
      this.enemies.set(remote.id, enemy);
      this.registerCombatTarget(remote.id, remote.entityGeneration ?? this.nextEnemyGeneration++);
      if (remote.claw) enemy.applyClawAttackState(remote.claw);
      const pendingClaw = this.pendingClawEvents.get(remote.id);
      if (pendingClaw) { this.pendingClawEvents.delete(remote.id); this.applyClawEvent(pendingClaw); }
      if (this.remoteSnapshotSeen && !remote.burrowed) this.playSpawnEffect(enemy, {});
      // Nach dem Registrieren, damit die Buddel-Visuals den Gegner bereits finden.
      if (remote.burrowed) this.setEnemyBurrowed(remote.id, true);
      return;
    }

    const wasBurrowed = enemy.isBurrowed();
    if (remote.claw) enemy.applyClawAttackState(remote.claw);
    if (remote.burrowed !== undefined) this.setEnemyBurrowed(remote.id, remote.burrowed);

    if (remote.hp !== undefined || remote.maxHp !== undefined) {
      enemy.setHp(remote.hp ?? enemy.getHp(), remote.maxHp ?? enemy.getMaxHp(), wasBurrowed);
    }
    if (remote.burnStacks !== undefined || remote.burnVisualStyle !== undefined) {
      const currentBurn = enemy.getNetSnapshot();
      enemy.updateBurnStacks(
        remote.burnStacks ?? currentBurn.burnStacks,
        remote.burnVisualStyle ?? currentBurn.burnVisualStyle ?? 'normal',
      );
    }
    if (remote.plasmaChargeStacks !== undefined) {
      enemy.updatePlasmaChargeStacks(remote.plasmaChargeStacks);
    }
    if (remote.dashPhase !== undefined) enemy.setDashPhase(remote.dashPhase);
    if (remote.specialAction !== undefined) {
      const current = enemy.getNetSnapshot();
      enemy.setSpecialAction(
        remote.specialAction,
        remote.specialActionEndsAt ?? current.specialActionEndsAt,
        remote.gaussChargeProgress ?? current.gaussChargeProgress,
        remote.gaussAimAngle ?? current.gaussAimAngle,
      );
    }
    if (remote.x !== undefined || remote.y !== undefined) {
      enemy.setTargetPosition(remote.x ?? enemy.sprite.x, remote.y ?? enemy.sprite.y, remote.positionRevision);
    }
    if (remote.rot !== undefined) {
      enemy.setTargetRotation(remote.rot);
    }
  }

  private generateEnemyId(_kind: CoopDefenseEnemyKind): string {
    return `e${(this.nextEnemyIdSeq++).toString(36)}`;
  }

  private gridToWorld(gridX: number, gridY: number): { x: number; y: number } {
    if (!this.worldMetrics) {
      throw new Error('[EnemyManager] WorldMetrics must be assigned before spawning an enemy');
    }
    return {
      x: this.worldMetrics.offsetX + gridX * CELL_SIZE + CELL_SIZE * 0.5,
      y: this.worldMetrics.offsetY + gridY * CELL_SIZE + CELL_SIZE * 0.5,
    };
  }
}
